import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, texture } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh, Vector3, DoubleSide } = THREE;

  const group = new Group();

  const atlasRect = { x: 0, y: 0, w: 512, h: 320 };
  const aspect = atlasRect.w / atlasRect.h;
  const planeHeight = 1.4;
  const planeWidth = planeHeight * aspect;

  const geometry = new PlaneGeometry(planeWidth, planeHeight);
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    depthWrite: false,
  });

  const mesh = new Mesh(geometry, material);
  const camPos = new Vector3();
  mesh.onBeforeRender = (renderer, scene, camera) => {
    camera.getWorldPosition(camPos);
    mesh.lookAt(camPos);
  };
  group.add(mesh);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.needsUpdate = true;

      const imgW = tex.image.width || atlasRect.w;
      const imgH = tex.image.height || atlasRect.h;

      const uMin = atlasRect.x / imgW;
      const vMin = 1 - (atlasRect.y + atlasRect.h) / imgH;
      const uMax = (atlasRect.x + atlasRect.w) / imgW;
      const vMax = 1 - atlasRect.y / imgH;

      const atlasUV = uv()
        .mul(vec2(uMax - uMin, vMax - vMin))
        .add(vec2(uMin, vMin));

      material.colorNode = texture(tex, atlasUV);
      material.needsUpdate = true;
    });
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
  };

  return group;
}
